      "latinTitle": "Bab 6 - Teks 2: Aktivitas Rumah di Malam Hari",
      "topicId": "yaumiyyah",
      "arabicText": "يَرْجِعُ عُثْمَانُ مِنَ الْمَدْرَسَةِ فِي السَّاعَةِ الثَّانِيَةِ ظُهْرًا. بَعْدَ الْوُصُوْلِ إِلَى الْبَيْتِ، يَخْلَعُ زِيَّ الْمَدْرَسَةِ وَيَغْسِلُ يَدَيْهِ وَوَجْهَهُ، ثُمَّ يَتَنَاوَلُ الْغَدَاءَ مَعَ أُمِّهِ وَأُخْتِهِ. فِي السَّاعَةِ الرَّابِعَةِ عَصْرًا، يُصَلِّي الْعَصْرَ وَيَسْتَرِيْحُ قَلِيْلًا فِي الْحَدِيْقَةِ.\n\nفِي الْمَسَاءِ، بَعْدَ صَلَاةِ الْمَغْرِبِ، يَقْرَأُ عُثْمَانُ الْقُرْآنَ ثُمَّ يَتَنَاوَلُ الْعَشَاءَ. وَبَعْدَ صَلَاةِ الْعِشَاءِ، يَذْهَبُ إِلَى غُرْفَةِ الْمُذَاكَرَةِ لِيَكْتُبَ الْوَاجِبَ الْمَنْزِلِيَّ وَيُرَاجِعَ الدُّرُوْسَ. يُشَاهِدُ التِّلْفَازَ لِمُدَّةِ نِصْفِ سَاعَةٍ مَعَ الأُسْرَةِ، ثُمَّ يَنَامُ مُبَكِّرًا فِي السَّاعَةِ التَّاسِعَةِ لَيْلًا لِيَسْتَيْقِظَ نَشِيْطًا فِي الصَّبَاحِ.",
